from pathlib import Path
import json
ROOT=Path(__file__).resolve().parent
path=ROOT/'prompt-catalog.json'
catalog=json.loads(path.read_text(encoding='utf-8'))
catalog['canvas']='3f74df77-de59-4781-8cce-6f0f94176cbc'
STYLE='沿用参考概念右侧的清新柔和2D手绘微观幻想美术，奶油白、薄荷青、暖珊瑚为主，宽色块哑光、少量温暖细轮廓、柔和体积。病毒尺度的膜表面/组织液微区前哨，器官是大陆级区域；不能出现完整心脏、肺或整颗细胞，也不画植物叶片、叶脉、树、根、花、草、木头、人类铁砧或岩石。无人物、机器人、武器、文字、数字、标志、边框、水印、UI。'
SPRITE='只制作一个独立游戏精灵，不是大场景，不是联系表，不是多角度。相机统一3/4正交轻斜俯视，看到顶部与前方，正面略向右。画布1024×1024，主体居中，外轮廓占画布最长轴约68%，接地支脚的底部中心在像素(512,870)，完整保留轮廓和8%以上安全留白，不裁边，无大地面平台。均匀纯白#FFFFFF背景用于后期准确透明抠图，背景无灰影、无纸纹、无棋盘格；奶白实体有闭合浅暖灰轮廓，不透明主体与背景可分离，无地面投影、无外圈环境。'
TILE='制作一张1024×1024正方形无缝循环游戏地表纹理，正上方正交俯视，整张填满没有透明区域。相邻左右、上下四边连续衔接，四边无边框、无收边、无暗角、无中心构图、无方向性明暗渐变。无固有道路、无平台、无障碍、无建筑、无凝露道具、无人物、无文字。只用低对比细密柔软凝胶膜肌理，大面积平静，亮度变化很小，适合大量铺满战斗地面，绝不画成独立细胞拼盘或蜂窝格子。'
objects={
 'obstacle.protein-fibers':('蛋白纤维束障碍','一束低矮而扎实的弯曲蛋白纤维障碍，三到五条奶油白粗蛋白索相互缠绕，横向延展，局部带薄荷青结构节环和柔软珊瑚胶质连接点。像柔韧的分子束而不是木树、树根或岩石，轮廓宽低而清楚，结构集中紧凑，前缘接触膜面。'),
 'obstacle.membrane-folds':('膜褶皱障碍','一段连续起伏的厚生物膜褶皱障碍，像折起的凝胶隔膜，三道圆滑波浪组成宽低的挡体。奶白薄荷外膜、柔和暖珊瑚内侧，少量蛋白颗粒只在褶皱表面，不要叶脉和羽毛，不要独立细胞。底部收拢成清楚连续接地边缘。'),
 'anchor.healthy':('健康稳态锚','人工搭建的低矮生物膜稳态锚定结构：三组矮胖奶油色蛋白支架围住一滴稳定的薄荷凝露，支架间连接层叠半透明膜瓣，环形低座与四个短钝锚足紧凑相连。明确是工程装置，中心是小凝露和横向薄膜张力环，没有完整心形、心脏、肺部或细胞轮廓。健康状态整洁平衡，薄荷/奶白为主，少量珊瑚连接点。'),
 'anchor.infected':('感染稳态锚','与健康稳态锚完全同款的人工膜锚定装置：三组矮胖奶油蛋白支架、横向低环座、四个短钝锚足与中央小凝露。被感染后右上膜瓣向内卷曲，接缝附着灰紫与暖珊瑚斑块，凝露浑浊蜜粉色，局部结构轻微倾斜但保持整体识别。不画怪物眼口、完整心脏/肺/细胞、黑暗霓虹、发光尖刺。两种状态具有相同尺寸与接地方式。'),
 'nutrient.healthy':('健康营养凝露节点','微观营养凝露采集节点：三枚彼此相连的大中小半透薄荷凝胶滴，被低矮奶白蛋白托环和短分子抓臂轻轻固定，底部是一枚紧凑膜瓣托盘。轮廓是宽底凝露聚合结构，顶部圆润，健康纯净，局部象牙高光柔和，不能像一棵花/树/蘑菇，也不能像完整细胞。道具朝前右，独立一件。'),
 'nutrient.infected':('感染营养节点','与健康营养凝露节点同款同轮廓：三枚彼此相连的大中小凝胶滴，由低矮奶白蛋白托环和短分子抓臂固定，紧凑膜瓣托盘。感染凝露呈浑浊暖珊瑚和灰紫，内部少量深紫色沉积团，托环一侧附着小片卷曲膜污染，受污染但不腐烂血腥、不长眼口、不像完整细胞或植物。保持柔和游戏画风与清楚可读的宽底轮廓。'),
 'summon.bloodstream-platform':('血流接引台','一座人工搭建的小型血流接引台：低矮扁椭圆奶油蛋白基座，上方一圈六片柔软薄荷膜瓣张开组成环形捕获装置，中央有透明凝胶通道，两束柔和暖珊瑚与奶金流体光带沿环口回旋并收束。装置完整、独立、紧凑，可近身操作，作为营地补给院设施，视觉体量约仓库的0.65倍。光带靠近实体不延伸全画布，清楚结构轮廓，不能像树叶、花、人体血管或传送门石碑。没有外置大地面、台阶、文字和外框。'),
 'summon.golden-antibody':('金抗体灵幻体','单个金抗体灵幻结构：由一根短粗下臂与两根向上分开的抗原结合臂组成清楚的Y形抗体意象，整体半透明温润奶金凝胶质感。两端是圆润分叉蛋白夹口，关节处以薄柔软膜带连接，体积集中，柔和金光只沿实体边缘，少量小金粒靠近实体。无脸、无眼口、无人形、无手脚、无衣服、无武器、无翅膀、无心形、无十字架。像珍贵但可亲的分子灵幻体，保持半透明金色层次与清晰外轮廓，不是UI卡牌，不画外框。虚拟落脚基准为Y形下臂底端，靠近(512,870)。')
}
sources=catalog['sources']
sources['ground.healthy']={'title':'健康微观地表','prompt':STYLE+TILE+'健康状态是平静的薄荷灰绿与奶白凝胶膜，极少量暖珊瑚细点。膜纤维细密、柔软、稀疏而无方向，大色块明度统一，纹理对比比场景道具低很多。','resolution':'1K'}
sources['ground.infected']={'title':'感染微观地表','prompt':STYLE+TILE+'感染状态是柔和暖珊瑚膜面混合少量低饱和灰紫蛋白沉积，浑浊薄膜和细小斑纹均匀低对比，仍明亮柔和，不能血腥、不能黑色毒液或高亮裂缝。纹理对比比场景道具低很多。','resolution':'1K'}
for key,(title,detail) in objects.items(): sources[key]={'title':title,'prompt':STYLE+SPRITE+detail,'resolution':'1K'}
ICON='制作一枚512×512可用于游戏背包的独立图标，单个物件，居中，四周保留15%安全留白，轮廓清楚，缩小到48像素仍可分辨。3/4轻斜俯视，均匀纯白#FFFFFF底用于后期透明抠图，无地面阴影，无棋盘格、无外框、无底板。'
sources['icon.model-fragment']={'title':'型号碎片','prompt':STYLE+ICON+'一片有辨识度的抗体型号碎片，形状为Y形蛋白结构的一截弯曲双叉端，奶白主体与薄荷青膜状嵌面，断面有两三个圆润蛋白接口，少量暖珊瑚注册结点。不画文字或型号数字，不是金属齿轮，不是宝石碎块，不是一堆碎片。','resolution':'1K'}
sources['icon.divine-forge-core']={'title':'神级锻造核心','prompt':STYLE+ICON+'一枚神级分子锻造核心，圆润奶金蛋白环抱住小颗深暖金凝胶核，三道紧凑薄膜环层交错，轮廓接近矮胖六边/三瓣聚合体，以清楚实心大体块表现珍贵，极少量柔光，金珊瑚为主、薄荷接口点缀。不画人类铁砧、火焰、眼睛、心脏、完整细胞、文字或星级外框。','resolution':'1K'}
path.write_text(json.dumps(catalog,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'prepared':list(sources),'count':len(sources)},ensure_ascii=False))
